import{z as o,x as l,o as B,c as p,q as n,j as r,D as e,d as i,s,S as A,b as E}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"不完全信息与贝叶斯纳什","description":"","frontmatter":{"title":"不完全信息与贝叶斯纳什","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/bayesian-nash.md","filePath":"econ/bayesian-nash.md","lastUpdated":1791413859000}'),d={name:"econ/bayesian-nash.md"};function h(m,a,_,c,C,N){const t=l("Mermaid");return B(),p("div",null,[a[2]||(a[2]=n('<h1 id="不完全信息与贝叶斯纳什" tabindex="-1">不完全信息与贝叶斯纳什 <a class="header-anchor" href="#不完全信息与贝叶斯纳什" aria-label="Permalink to &quot;不完全信息与贝叶斯纳什&quot;">​</a></h1><div class="epigraph"><p>不完全信息博弈可改写为：自然先抽类型，每人只知己型，对他人类型持有共同先验；均衡是类型依存策略的纳什。</p><footer>—— Harsanyi, Games with Incomplete Information Played by “Bayesian” Players, Management Science, 1967–68</footer></div><p><a href="/econ/war-of-attrition">上一课</a>（消耗战）在完全信息下已经需要混合均衡，租金耗散在等待里。缺口是：许多人连对手的支付都不知道——成本、估值、风险厌恶都是私型。此时「给定 \\(s_{-i}\\) 的最优反应」没有定义，因为 \\(u_{-i}\\) 未知。Harsanyi 的办法是把未知写成自然的行动，用共同先验把博弈变回完全但不完美信息。本课钉贝叶斯纳什（BNE），不管信号发出后信念如何精炼。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>不完全信息：至少一人不确定另一人的支付或可行集。直接写策略式会漏掉「我知道你不知道我知道」的层级。Harsanyi 转化：类型空间 \\(\\Theta_i\\)，共同先验 \\(p\\)，条件信念 \\(p(\\theta_{-i}\\mid\\theta_i)\\)。策略是 \\(\\sigma_i:\\Theta_i\\to\\Delta(S_i)\\)。支付是对类型与行动的期望。BNE 是：每个类型 \\(\\theta_i\\) 的 \\(\\sigma_i(\\theta_i)\\) 最大化给定他人策略与后验时的期望效用。</p><p><span class="marginnote">Harsanyi 转化的大白话：把「我不知道你的成本」改写成「自然先掷骰子决定你的类型——你看得见自己的骰子，我看不见，但我们都同意骰子的概率」。未知变成看不见，博弈就能用回完全信息的工具箱，只是多了一位先手玩家。</span></p><p>这正是一个更大策略式的纳什：玩家是「类型–个人」，或等价地原玩家在自然行动之后行动。有限类型、有限行动时，<a href="/econ/mixed-strategy">混合存在性</a>直接给出 BNE 非空。</p><h3 id="共同先验不是「大家都一样聪明」" tabindex="-1">共同先验不是「大家都一样聪明」 <a class="header-anchor" href="#共同先验不是「大家都一样聪明」" aria-label="Permalink to &quot;共同先验不是「大家都一样聪明」&quot;">​</a></h3><p>共同先验是技术假设：差异只来自私型，不来自对世界的任意异质信念。放松它会得到「没有共同知识」的另一套理论，主干不走。BNE 也不要求类型被对方观测；若类型后来变成信号，那是下一课的树。</p><p><span class="marginnote">拍卖是标准教具：每人估值 \\(v_i\\) 私有，出价是类型依存策略。第一价格密封的 BNE 是「出价低于估值」的遮挡均衡，不是完全信息下的伯川德。先验与独立假设改均衡函数。</span></p><p>类型可以是连续统，策略变成函数 \\(b(v)\\)。存在性要另加技术条件；本课有限类型已经够把 Harsanyi 转化钉住。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对象：有限类型、有限行动、共同先验、风险中性或 vNM 效用。解：BNE。计算：对每一类型写最优反应，注意积分里是对他人类型的期望，不是对一个确定的 \\(s_{-i}\\)。纯策略 BNE 仍可空，混合在类型依存策略上取。</p><p>与完全信息纳什的关系：若 \\(|\\Theta_i|=1\\) 对所有 \\(i\\)，BNE 退化为纳什。不完全信息不是新偏好，是类型上的期望。</p>',14)),(B(),r(A,null,{default:e(()=>[s(t,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20INC%5B%22%E6%94%AF%E4%BB%98%E6%9C%AA%E7%9F%A5%22%5D%20--%3E%20HAR%5B%22%E8%87%AA%E7%84%B6%E6%8A%BD%20%CE%B8%EF%BC%8C%E5%85%B1%E5%90%8C%E5%85%88%E9%AA%8C%22%5D%0A%20%20HAR%20--%3E%20STR%5B%22%E7%AD%96%E7%95%A5%EF%BC%9A%CE%B8%20%E2%86%92%20%E8%A1%8C%E5%8A%A8%22%5D%0A%20%20STR%20--%3E%20BNE%5B%22%E6%AF%8F%E4%B8%AA%E7%B1%BB%E5%9E%8B%E9%83%BD%E6%9C%80%E4%BC%98%E5%8F%8D%E5%BA%94%22%5D%0A%20%20BNE%20--%3E%20SIG%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E8%A1%8C%E5%8A%A8%E8%A2%AB%E7%9C%8B%E8%A7%81%EF%BC%8C%E4%BF%A1%E5%BF%B5%E8%A6%81%E6%9B%B4%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[i(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[i("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,"类型把「我以为你以为」收成对先验的贝叶斯更新。均衡一致性是：我用来算你行动的分布，正是你各类型的策略对先验的推送。没有这层，最优反应会对错的对手分布取期望。",-1)),a[5]||(a[5]=E("p",null,[E("span",{class:"marginnote"},"数字实例：两人第一价格拍卖、估值各自均匀分布在 0 到 100，BNE 是每人只报估值的一半：估值 80 的人出 40。一个「人」的连续类型各自做各自的最优——策略 \\(b(v)=v/2\\) 是 100 种类型写成的同一张出价表。")],-1)),(B(),r(A,null,{default:e(()=>[s(t,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20N%5B%22%E8%87%AA%E7%84%B6%E6%8C%89%E5%85%B1%E5%90%8C%E5%85%88%E9%AA%8C%E6%8A%BD%E5%90%84%E4%BA%BA%E7%9A%84%E7%B1%BB%E5%9E%8B%22%5D%20--%3E%20K%5B%22%E6%AF%8F%E4%BA%BA%E5%8F%AA%E7%9C%8B%E8%A7%81%E8%87%AA%E5%B7%B1%E7%9A%84%E7%B1%BB%E5%9E%8B%22%5D%0A%20%20K%20--%3E%20B%5B%22%E5%AF%B9%E4%BB%96%E4%BA%BA%E7%B1%BB%E5%9E%8B%E5%BD%A2%E6%88%90%E6%9D%A1%E4%BB%B6%E4%BF%A1%E5%BF%B5%22%5D%0A%20%20B%20--%3E%20S%5B%22%E6%AF%8F%E4%B8%AA%E7%B1%BB%E5%9E%8B%E5%90%84%E8%87%AA%E9%80%89%E6%9C%80%E4%BC%98%E8%A1%8C%E5%8A%A8%22%5D%0A%20%20S%20--%3E%20P%5B%22%E7%AD%96%E7%95%A5%E5%AF%B9%E5%85%88%E9%AA%8C%E7%9A%84%E6%8E%A8%E9%80%81%20%3D%20%E4%BB%96%E4%BA%BA%E7%8C%9C%E6%B5%8B%E7%9A%84%E5%88%86%E5%B8%83%22%5D%0A%20%20P%20--%3E%20C%5B%22%E4%B8%A4%E8%BE%B9%E5%AF%B9%E4%B8%8A%EF%BC%9A%E5%9D%87%E8%A1%A1%E4%B8%80%E8%87%B4%EF%BC%8C%E5%8D%B3%20BNE%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[i(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=n('<p><a href="/econ/folk-theorem">无名氏定理</a>在完全信息下过肥；一引入类型（声誉），有限次重复也可以撑住合作，因为偏离会暴露类型。这是 BNE 的动态版，本课只钉静态转化：自然先动，其余同时选类型依存策略。静态 BNE 不约束「零概率类型」上的行为——那些类型达不到，看见一个不该出现的行动时，后验没有贝叶斯定义。下一课把信念写成均衡的一部分，专门管这些信息集。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>先验从哪来，理论不回答。连续类型要技术条件保证存在。关联价值、公共价值拍卖里，赢者诅咒来自条件期望，仍是 BNE，只是信息结构变了。机制设计会把 BNE 当约束：任何机制的均衡结果必须能被激励相容说圆，那是显示原理。</p><p><span class="marginnote">常见误区：以为 BNE 里「大家对真相看法不同」等于不理性。共同先验恰恰规定分歧只来自私有信息，没人对先验本身有异议；允许任意异质信念是另一套更松的理论。把两者混了，会误判均衡里谁在「犯错」。</span></p><p>独立私值是最瘦的先验；一旦类型相关，条件期望跟着赢者诅咒走，仍是 BNE，只是积分核变了。</p><p>后课默认：不完全信息先写成 Harsanyi 类型与 BNE；行动成为信号时，再加信念精炼。</p><h3 id="每个类型各自最优-不是平均类型最优" tabindex="-1">每个类型各自最优，不是平均类型最优 <a class="header-anchor" href="#每个类型各自最优-不是平均类型最优" aria-label="Permalink to &quot;每个类型各自最优，不是平均类型最优&quot;">​</a></h3><p>Harsanyi 不要求人人类型相同，只要求对抽出看法一致。策略随己型变；别人看到的是策略对先验的混合物。不要把「平均类型的最优」当成每个类型的最优：高估值该出更高的价，低估值不该去模仿那个价，除非激励相容恰好允许。第一价格密封的遮挡均衡是 BNE，支付等价要到机制设计才写。静态 BNE 也不给「看见偏离之后怎么想」；那一列信念是下一课才进入均衡定义的对象。</p><p>独立私值是最瘦的先验。类型一旦相关，赢者的条件期望更差，出价函数再削一刀，解概念仍是 BNE。本课不把拍卖写成限价簿排队。</p><p><span class="marginnote">有限类型、有限行动时，把每个类型当成虚拟局中人，存在性回到混合纳什的角谷。连续类型要技术条件，本课不列。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>不完全信息用类型与共同先验改写成完全但不完美信息。</li><li>BNE 是类型依存策略的纳什；有限时存在。</li><li>共同先验把信念差异限制为私型。</li><li>静态 BNE 不管零概率偏离上的信念。</li><li>出处：Harsanyi, <em>Management Science</em>, 1967–68。</li></ul>',12))])}const D=o(d,[["render",h]]);export{u as __pageData,D as default};
